insert into equipment_categories (id, slug, name, description) values
  ('41e7596a-a20d-579c-bf8f-97e9d4d68f90', 'indoor-led', 'Indoor LED', 'Fine-pitch indoor LED panels for stage backdrops, exhibition walls, and broadcast-grade displays, sized and pitched to viewing distance.'),
  ('0845907f-81e5-58bb-8242-f7d29c19ab63', 'outdoor-led', 'Outdoor LED', 'Weatherproof, high-brightness LED for outdoor stages, ceremonies, and large-format brand activations that need to hold up in daylight.'),
  ('64226ae0-a90f-5570-8c0a-9aa6662e254b', 'audio', 'Audio Systems', 'Line array PA, monitor systems, digital mixing, wireless microphones, and interpretation audio, specified to room size and program type.'),
  ('dc50a406-72a2-5a43-92ad-f187fa557974', 'lighting', 'Lighting Systems', 'Moving lights, architectural wash, and console-driven programming for stage lighting, keynote lighting, and ambient venue design.'),
  ('7a6ecd4f-fec0-5175-9515-788442c38c3c', 'stage', 'Stage & Set', 'Modular staging, decking, and custom set elements engineered to venue load limits and built to strike as fast as they go up.'),
  ('40c82f4b-eeba-599e-9ac8-1835f24df6fd', 'truss', 'Truss & Rigging', 'Ground support and motorized rigging systems for LED, lighting, and speaker arrays, signed off against certified load calculations.'),
  ('7b444a28-4071-5315-ae17-0ebf37598392', 'projectors', 'Projectors', 'High-lumen laser projection for stage backdrops, projection mapping, and large-venue rear or front projection.'),
  ('9eaef7be-aa6c-5a6f-ac49-80e3a8b2e8cb', 'displays', 'Displays & Signage', 'Freestanding and mounted displays for wayfinding, registration, exhibition booths, and digital signage networks.'),
  ('399b2066-bb90-5ef1-bc1b-ae48c5ff84b6', 'cameras', 'Camera Systems', 'Broadcast and PTZ camera systems, vision switching, and live production kits for streaming, recording, and IMAG.'),
  ('48b5ed52-b7db-5155-976a-02ef53b7aaef', 'accessories', 'Accessories & Support', 'Power distribution, cabling, cases, and the technical support infrastructure that keeps a production running end to end.');
insert into blog_categories (id, slug, name) values
  ('8f004ec7-48e0-5288-b6e3-edc0e266429c', 'event-planning', 'Event Planning'),
