insert into faqs (id, question, answer, category) values
  ('2caee977-936e-5a62-b6bd-8a4cf9a1842e', 'What kinds of clients does TOTAL MEDIA work with?', 'We work with international corporations, Japanese enterprises, event and PR agencies, exhibition organizers, government bodies, universities, hotels and MICE venues, and luxury brands operating in Japan. Roughly half of our engagements involve at least one non-Japanese stakeholder, so bilingual project management is standard on every account, not an add-on.', 'general'),
  ('d6977ac5-b10e-591d-8a42-64012f193dce', 'Do you operate outside Tokyo?', 'Yes. We deliver events across Japan — from major convention centers in Tokyo, Osaka, and Nagoya to regional venues, hotel ballrooms, and outdoor sites nationwide. Our equipment and crew logistics are built around national coverage, not a single-city footprint.', 'general'),
  ('7264c6b4-ae95-5642-9405-2a9aa0a86f5a', 'How long does it take to receive a quote?', 'Standard requests through our Request a Quote form receive a detailed proposal within one to two business days. Complex, multi-day, or hybrid productions with custom technical designs typically take three to five business days, since we prepare an initial technical plan alongside the quote rather than a rough estimate.', 'quotes-pricing'),
  ('05d75b48-fe76-5907-b469-c31b6adda60e', 'How is pricing structured?', 'Pricing depends on event format, venue, duration, equipment specification, and staffing needs — there is no flat rate, because a boardroom AV setup and a two-day hybrid conference are fundamentally different jobs. Every proposal itemizes equipment, labor, and production management separately so you can see exactly what you are paying for and adjust scope if needed.', 'quotes-pricing'),
  ('7ea28b0c-bd29-5be0-ae61-cb3ee56184dd', 'What are your payment terms?', 'Most engagements require a signed proposal and a deposit to confirm the date and reserve equipment and crew, with the balance due on a schedule agreed in the contract — typically before or shortly after the event, depending on client type and event size. Government and university clients can be accommodated under standard procurement and invoicing cycles.', 'quotes-pricing'),
  ('13bcab44-d89e-5be1-9fd0-26eaa817d3c6', 'Can we rent equipment only, without your production team?', 'Yes. Equipment rental is available on its own for clients who have in-house technical staff or an existing production partner. That said, most first-time clients find that adding our technicians for setup, operation, and strike is a small cost relative to the risk of running unfamiliar equipment without support on the day.', 'equipment'),
  ('9aa76360-f299-579b-90ab-75d5accee25d', 'What equipment brands and standards do you work with?', 'Our LED, audio, lighting, and rigging inventory is sourced to broadcast and touring-grade specification, maintained on a fixed inspection schedule, and rotated regularly rather than run to end of life. Full specifications for each category are listed on the equipment catalogue, and we''re glad to confirm exact models for a given proposal.', 'equipment'),
  ('1c222cfd-9290-5a6a-9d76-4ddabfa5dcfc', 'How far in advance should we book?', 'For standard corporate events and conferences, four to six weeks gives us comfortable room for planning, venue coordination, and equipment allocation. Large exhibitions, award ceremonies, or events requiring custom staging and international logistics benefit from eight to twelve weeks. We do take on shorter-notice requests when our schedule allows — reach out and we''ll tell you honestly whether the timeline works.', 'planning'),
  ('907dc7f2-a472-5b73-8f9d-80713b6492b5', 'Do you conduct site visits before an event?', 'For any event involving structural rigging, large-format LED, or a venue we haven''t worked in before, yes — a technical site visit or a detailed floor plan and load-in review is standard practice, not optional. It''s how we catch power, access, and rigging constraints before they become event-day problems.', 'planning'),
  ('50b0d9c4-013b-5627-96e7-3628eb24c8ee', 'Can you support events run partly or entirely in English?', 'Yes — bilingual (Japanese/English) project management and on-site coordination are standard for our international clients, and we regularly support simultaneous interpretation booths, multilingual signage, and run-of-show documentation in both languages.', 'planning'),
  ('1bf130f7-3476-5c2a-84e2-7eda6b1d877a', 'How do you ensure reliability for live streaming and hybrid events?', 'Every hybrid or virtual production runs on redundant internet circuits, backup encoding paths, and a dedicated technical director monitoring the stream separately from the in-room show — so a connectivity issue on one path doesn''t take the broadcast down. We also run a full technical rehearsal against the live platform before any hybrid event, not just a sound check.', 'technical'),
  ('d9ed0ab4-af79-5997-bc35-fb0a043048f0', 'How do you handle power and rigging safety?', 'All power distribution and structural rigging is designed and signed off by licensed technicians against the venue''s documented load limits, with redundant circuits for anything broadcast-critical. This is treated as a compliance requirement, not a line item to shortcut on tighter budgets.', 'technical'),
  ('d5fe5b28-5237-5281-bd57-3f04bf9f8292', 'How is TOTAL MEDIA different from a pure equipment rental company?', 'Equipment rental is one part of what we do, not the business itself. Our team plans the event, designs the technical production, manages the exhibition or conference on-site, and operates the equipment — which means one accountable partner instead of you coordinating separate vendors for planning, staging, AV, and streaming.', 'general'),
  ('e9878aae-38b2-599d-9a0c-358d29a494fc', 'Can you staff large, multi-day events?', 'Yes. Our production and technical staffing scales from a single technician supporting a boardroom meeting to full crews covering multi-day, multi-hall exhibitions with parallel sessions, live streaming, and simultaneous interpretation running at once.', 'planning');
insert into industries (id, slug, name, description, use_cases) values
  ('3606726f-1678-5440-81cf-c149a4c09f6d', 'international-companies', 'International Companies', 'Global organizations entering or expanding in Japan need a production partner who can translate a regional or global event standard into local execution — venue norms, permitting, language, and vendor practices included.', ARRAY['Regional headquarters launches and town halls', 'APAC sales kickoffs and partner conferences', 'Global brand campaigns adapted for the Japan market']::text[]),
  ('e18ca873-cdf6-5a5c-80e9-788d465fecb5', 'japanese-corporations', 'Japanese Corporations', 'Established Japanese enterprises rely on us for the technical precision and quiet reliability their internal stakeholders expect, from shareholder meetings to nationwide dealer conferences.', ARRAY['Shareholder and general meetings', 'Internal conferences and dealer/agency events', 'New product and service announcements']::text[]),
  ('d55bac9e-7f7d-561b-8614-d7068673e5f7', 'event-agencies', 'Event & PR Agencies', 'Agencies bring us in as the technical production partner behind their creative and client relationship — we work under your brand, in your run-of-show, without friction.', ARRAY['White-label technical production for agency-led events', 'Rapid-turnaround activations and press events', 'Multi-market campaigns requiring a Japan production partner']::text[]),
  ('05149faa-b271-5cb0-b974-09d8a06e2b45', 'exhibition-organizers', 'Exhibition Organizers', 'Trade show and exhibition organizers need a partner who understands hall logistics, exhibitor coordination, and the compressed build/strike windows unique to large-format events.', ARRAY['Convention center-scale trade shows', 'Multi-hall exhibitions with parallel programming', 'Exhibitor booth and pavilion technical services']::text[]),
  ('61665411-fd5b-549c-b402-4b086adfd7ef', 'government-organizations', 'Government Organizations', 'Public-sector events carry procurement, security, and protocol requirements that differ materially from corporate work — we run to that standard as a matter of course.', ARRAY['Ministry and municipal conferences and forums', 'Public consultations and press briefings', 'International summits and diplomatic events']::text[]),
  ('52733a92-9818-5c21-81ed-7ce8cb60603c', 'universities', 'Universities & Academic Institutions', 'From academic symposia to graduation ceremonies, university events combine large audiences, strict scheduling, and often a hybrid or livestreamed component for remote attendees and alumni.', ARRAY['International symposia and research conferences', 'Graduation and commencement ceremonies', 'Open campus events and admissions presentations']::text[]),
  ('cf79d855-b332-5c78-81cf-b995e7718f89', 'hotels', 'Hotels & MICE Venues', 'We partner with hotel and venue teams as a preferred technical vendor — supplying equipment, engineering, and crew that meet the venue''s house standards without disrupting their operations.', ARRAY['Ballroom and banquet AV upgrades for signature events', 'Preferred-vendor technical partnerships', 'Convention and conference center production support']::text[]),
  ('48f941a3-4ec8-5a2b-9139-4cf8f3ad7db8', 'mice-clients', 'MICE Clients', 'Meetings, incentives, conferences, and exhibitions each carry a distinct production profile — we scope and staff to the specific format rather than applying one template across all four.', ARRAY['Incentive programs with hybrid and satellite audiences', 'Multi-day congress and convention production', 'Executive meetings requiring discretion and precision']::text[]),
  ('b7b85d9c-9e00-547f-b3e8-0420305b9d02', 'luxury-brands', 'Luxury Brands', 'Luxury clients expect production values that match the brand itself — refined lighting and staging, silent, disciplined crews, and zero tolerance for visible technical seams.', ARRAY['Product launches and press previews', 'Flagship store openings and brand experiences', 'VIP and press event hospitality production']::text[]);
insert into services (id, slug, category, name, short_description, hero_statement, overview, capabilities, process, ideal_for, seo_title, seo_description) values
  ('511aadc2-9574-55c9-aba3-b80d3e583f36', 'corporate-events', 'event-type', 'Corporate Events', 'End-to-end planning and technical production for internal and client-facing corporate events of any scale.', 'Corporate events, produced the way your organization needs to be seen.', ARRAY['Corporate events carry a brand and an internal culture at the same time — a town hall says as much about a company as a client dinner does. We plan and produce both, working from your objectives and audience rather than a fixed event template.', 'Our teams handle logistics, venue coordination, technical production, and on-site management as one accountable service, so your internal stakeholders have a single point of contact instead of a coordination burden layered on top of their day job.']::text[], ARRAY['Full event planning and project management from brief to strike', 'Venue sourcing and technical site assessment', 'Stage, AV, and lighting design suited to the room and audience', 'On-site event management and run-of-show execution', 'Bilingual (Japanese/English) coordination for international stakeholders', 'Post-event reporting and asset handover']::text[], '[{"title":"Brief & Objectives","description":"We start with what the event needs to achieve for your organization, not a generic checklist."},{"title":"Design & Proposal","description":"A detailed technical and logistical plan with transparent, itemized pricing."},{"title":"Production","description":"Build, technical rehearsal, and event-day management by the same team that designed it."},{"title":"Strike & Report","description":"Clean teardown and a post-event summary covering what worked and what to refine next time."}]'::jsonb, ARRAY['Town halls and internal announcements', 'Client appreciation events', 'Leadership offsites', 'Company milestone celebrations']::text[], 'Corporate Event Production Services in Japan | TOTAL MEDIA', 'Full-service corporate event planning and production across Japan — venue sourcing, technical design, and on-site management from one accountable team.'),
  ('c7a60f73-3e9b-5efd-bdfb-f00386f34023', 'conferences', 'event-type', 'Conferences', 'Multi-session conference production with reliable AV, staging, and run-of-show discipline at scale.', 'Conferences run on discipline as much as design — we bring both.', ARRAY['A conference is a schedule under pressure: parallel sessions, speaker changeovers, and an audience that notices every delay. We build the technical infrastructure and the run-of-show discipline to keep that schedule intact.', 'From single-track keynote conferences to multi-hall programs with breakout rooms, we scale crew, equipment, and stage management to match session count and audience size, not a one-size template.']::text[], ARRAY['Main stage and breakout room AV design', 'Speaker management and presentation handling', 'Stage management and run-of-show coordination', 'Simultaneous interpretation booth setup and support', 'Registration and wayfinding signage integration', 'Live streaming of keynote and breakout sessions']::text[], '[{"title":"Program Mapping","description":"We map your session schedule to technical requirements room by room."},{"title":"Technical Design","description":"Stage, AV, and interpretation infrastructure specified to each room''s size and program."},{"title":"Rehearsal","description":"Full technical rehearsal with speakers and stage management before doors open."},{"title":"Live Execution","description":"On-site stage management holding every room to schedule in parallel."}]'::jsonb, ARRAY['Industry and academic conferences', 'Multi-track corporate summits', 'Annual company conferences', 'Partner and dealer conferences']::text[], 'Conference Production & Technical Services in Japan | TOTAL MEDIA', 'Multi-session conference production across Japan — stage management, AV design, interpretation support, and live streaming for programs of any scale.'),
  ('e47069eb-5728-5378-9941-300f000a52aa', 'exhibitions', 'event-type', 'Exhibitions', 'Exhibition and booth technical production built for compressed build/strike windows and hall logistics.', 'Exhibitions live or die on the build window. We build to the clock.', ARRAY['Exhibition halls run on tight, non-negotiable build and strike schedules shared across every exhibitor on the floor. Our teams are built for that rhythm — fast, coordinated installs that still meet the technical and visual standard the exhibit deserves.', 'We manage booth AV, LED, and lighting technical production, and can coordinate directly with hall organizers and general contractors so your team isn''t chasing three vendors during load-in.']::text[], ARRAY['Booth and pavilion LED, AV, and lighting installation', 'Hall logistics and general contractor coordination', 'Rapid build/strike crews for compressed windows', 'Interactive display and digital signage integration', 'On-site technical support for the duration of the show', 'Power distribution and cable management to hall code']::text[], '[{"title":"Hall & Booth Review","description":"We review floor plans, power allocation, and hall rules before design begins."},{"title":"Technical Design","description":"LED, lighting, and AV specified to booth size and sightlines."},{"title":"Build","description":"Coordinated install crews working the compressed load-in window."},{"title":"Live Support","description":"Technicians on the floor for the run of the show, not just the install."}]'::jsonb, ARRAY['Trade show exhibitor booths', 'Brand pavilions', 'Public exhibitions and expos', 'Multi-day exhibition programs']::text[], 'Exhibition & Booth Production Services in Japan | TOTAL MEDIA', 'Exhibition and trade show booth technical production across Japan — LED, lighting, and AV installed to compressed build/strike schedules.'),
  ('69be129f-eb8c-5fe3-8804-698e9909b5c8', 'trade-shows', 'event-type', 'Trade Shows', 'Large-scale trade show production covering exhibitor technical services and organizer-side infrastructure.', 'Convention-scale trade shows, engineered for volume and repeatability.', ARRAY['Trade shows multiply exhibition complexity across dozens or hundreds of booths, parallel programming, and thousands of attendees. We support both exhibitor-side technical production and, for organizers, show-wide infrastructure like main stage AV and hall-wide signage.', 'Our staffing model scales to convention-center volume — repeatable booth builds, coordinated crews, and a single technical point of contact for organizers managing many moving parts at once.']::text[], ARRAY['Organizer-side main stage and show floor AV', 'Exhibitor technical services at scale', 'Multi-crew coordination across large hall footprints', 'Show-wide digital signage and wayfinding', 'Live streaming of main stage programming', 'On-call technical support desk for the duration of the show']::text[], '[{"title":"Show Scoping","description":"We align on organizer infrastructure needs and exhibitor service packages."},{"title":"Resource Planning","description":"Crew, equipment, and logistics scheduled against the full show timeline."},{"title":"Build & Show Days","description":"Coordinated multi-crew execution across the hall footprint."},{"title":"Strike","description":"Structured teardown sequenced to hall move-out deadlines."}]'::jsonb, ARRAY['Industry-wide trade shows', 'Consumer expos', 'Multi-hall convention center events', 'B2B trade fairs']::text[], 'Trade Show Production Services in Japan | TOTAL MEDIA', 'Convention-scale trade show production across Japan — main stage AV, exhibitor technical services, and multi-crew logistics for large shows.'),
  ('0c0cf37f-f4d1-547a-88d4-0ff0d44d1dd2', 'product-launches', 'event-type', 'Product Launches', 'High-impact product launch production where lighting, staging, and reveal mechanics carry the moment.', 'A launch has one moment that matters. We build the production around it.', ARRAY['A product launch succeeds or fails on a small number of seconds — the reveal, the first look, the photo that gets shared. We design lighting, staging, and technical sequencing around that moment specifically, then build everything else in support of it.', 'From press-only previews to large public launches, we treat the reveal mechanics — timing, lighting cues, camera coverage — as the core engineering problem, not a decoration on top of a standard stage build.']::text[], ARRAY['Reveal staging and mechanical/lighting cue design', 'Premium lighting design matched to brand and product', 'Multi-camera coverage for press and social capture', 'LED backdrop and projection integration', 'Press and media logistics coordination', 'Live streaming for remote press and audiences']::text[], '[{"title":"Moment Design","description":"We define the reveal sequence first, then engineer the production around it."},{"title":"Technical Build","description":"Lighting, staging, and cue systems built and cued precisely."},{"title":"Full Cue Rehearsal","description":"The reveal is rehearsed to the second, multiple times, before the room fills."},{"title":"Live Execution","description":"Cue-perfect execution with camera coverage for press and social assets."}]'::jsonb, ARRAY['Consumer and B2B product reveals', 'Flagship store and showroom openings', 'Press-only preview events', 'Automotive and technology launches']::text[], 'Product Launch Event Production in Japan | TOTAL MEDIA', 'Product launch production across Japan — reveal staging, premium lighting design, and multi-camera coverage built around the moment that matters.'),
  ('7e989ae8-7416-579d-8ef1-c817db14428b', 'award-ceremonies', 'event-type', 'Award Ceremonies', 'Broadcast-quality award ceremony production, from red carpet to stage to livestream.', 'Award ceremonies ask for television-grade production in a live room.', ARRAY['Award ceremonies combine formal programming, live presentation, and often broadcast or streaming distribution — closer to a television production than a standard corporate event. We bring the camera, lighting, and stage management discipline that format demands.', 'We manage the full sequence: arrivals and red carpet, stage presentation with precise cueing for winners and presenters, and, where needed, a clean live broadcast or stream for audiences who aren''t in the room.']::text[], ARRAY['Stage design and presentation lighting', 'Broadcast-style multi-camera direction and vision switching', 'Winner and presenter cueing and stage management', 'Red carpet and arrivals AV support', 'Live streaming and broadcast delivery', 'Orchestral or recorded music cue integration']::text[], '[{"title":"Program & Run-of-Show","description":"We build a precise run-of-show against the award sequence and presenter list."},{"title":"Technical Design","description":"Camera, lighting, and stage cueing systems designed to the format."},{"title":"Full Rehearsal","description":"A complete run-through with stand-ins before the live ceremony."},{"title":"Live Broadcast","description":"Directed multi-camera execution with stream/broadcast delivery."}]'::jsonb, ARRAY['Industry and corporate award ceremonies', 'Employee recognition galas', 'Academic and cultural award events', 'Televised or streamed ceremonies']::text[], 'Award Ceremony Production Services in Japan | TOTAL MEDIA', 'Broadcast-quality award ceremony production across Japan — stage design, multi-camera direction, and live streaming for formal presentation events.'),
  ('d55c1823-7d5d-5481-aa6a-4b81bfff23a3', 'virtual-events', 'event-type', 'Virtual Events', 'Fully virtual event production with studio-grade presentation and platform integration.', 'A virtual event is still a production — treat it like one.', ARRAY['Virtual events fail when they''re run like a video call instead of a production. We build them like a broadcast: a real studio or set, professional lighting and camera work, and a technical director managing the platform separately from the on-camera talent.', 'We integrate with the platform of your choice — webinar tools, virtual event platforms, or a custom stream — and manage speaker coordination, Q&A, and content playback so the live experience runs smoothly from the presenter''s side and the viewer''s side at once.']::text[], ARRAY['Studio and set design for virtual presentation', 'Multi-camera, multi-speaker production switching', 'Platform integration (webinar, virtual event, custom stream)', 'Remote speaker coordination and technical rehearsal', 'Live Q&A and audience interaction management', 'Recording and on-demand asset delivery']::text[], '[{"title":"Platform & Format Planning","description":"We confirm the platform, format, and speaker list before technical design."},{"title":"Studio Build","description":"Set, lighting, and camera production built to broadcast standard."},{"title":"Speaker Rehearsal","description":"Remote and in-studio speakers rehearsed on the live platform, not a placeholder."},{"title":"Live Direction","description":"Full production switching and platform monitoring through the live event."}]'::jsonb, ARRAY['Global product announcements', 'Virtual town halls', 'Webinar series requiring production value', 'Remote press events']::text[], 'Virtual Event Production Services in Japan | TOTAL MEDIA', 'Studio-grade virtual event production across Japan — multi-camera direction, platform integration, and speaker coordination for fully remote events.'),
  ('5105af91-91d2-5da4-acc4-d473190577bb', 'hybrid-events', 'event-type', 'Hybrid Events', 'In-room and remote audiences produced as one coherent event, not two separate ones.', 'One event, two audiences — designed together, not bolted together.', ARRAY['Most hybrid events are designed for the room and the stream gets whatever''s left over. We design for both audiences from the start — camera positions that don''t block sightlines, audio mixed for the room and the broadcast separately, and content built to work on a screen as well as it works live.', 'A dedicated technical director manages the remote broadcast independently of the in-room production team, so an issue on one side never becomes an issue on both.']::text[], ARRAY['Dual-audience technical and content design', 'Independent in-room and broadcast production teams', 'Remote speaker and panel integration', 'Redundant streaming infrastructure', 'Interactive tools for remote audience engagement', 'Simultaneous interpretation for in-room and remote audiences']::text[], '[{"title":"Dual-Audience Design","description":"Content and technical plans built for the room and the stream together."},{"title":"Infrastructure Build","description":"Redundant broadcast paths and in-room AV built and tested independently."},{"title":"Full Technical Rehearsal","description":"A live rehearsal against the actual streaming platform, not a sound check."},{"title":"Live Execution","description":"Parallel in-room and broadcast direction managed by dedicated teams."}]'::jsonb, ARRAY['Conferences with remote attendee tracks', 'Global town halls across time zones', 'Hybrid press events', 'Investor and shareholder meetings']::text[], 'Hybrid Event Production Services in Japan | TOTAL MEDIA', 'Hybrid event production across Japan — in-room and remote audiences designed as one event, with redundant streaming and dedicated broadcast direction.'),
  ('fa5100c1-aec8-5d54-b065-6847d84204d9', 'live-streaming', 'event-type', 'Live Streaming', 'Broadcast-grade live streaming with redundant infrastructure and dedicated technical direction.', 'Streaming infrastructure that treats "live" as a hard requirement.', ARRAY['A dropped stream is a visible failure in a way few other production issues are. We build streaming infrastructure around redundancy by default — dual internet circuits, backup encoding paths, and a technical director whose only job is watching the broadcast, separate from whoever is running the room.', 'We support single-camera webcast setups through full multi-camera broadcast direction, and integrate with the platform your audience already uses rather than forcing a new one on them.']::text[], ARRAY['Multi-camera live production and vision switching', 'Redundant internet circuits and encoding paths', 'Platform integration (YouTube Live, Vimeo, custom RTMP, webinar tools)', 'Live graphics, lower-thirds, and content overlay', 'Multi-language audio channel streaming', 'Recording, editing, and on-demand delivery']::text[], '[{"title":"Platform & Redundancy Plan","description":"We confirm the delivery platform and build redundancy into the plan from the start."},{"title":"Technical Build","description":"Camera, encoding, and network infrastructure installed and load-tested."},{"title":"Rehearsal on the Live Platform","description":"A full rehearsal against the actual streaming destination, not a local test."},{"title":"Live Broadcast","description":"Dedicated technical direction monitoring the stream throughout the event."}]'::jsonb, ARRAY['Conference and keynote streaming', 'Press conference broadcasts', 'Award ceremony and ceremony streaming', 'Multi-language broadcast programs']::text[], 'Live Streaming & Broadcast Services in Japan | TOTAL MEDIA', 'Broadcast-grade live streaming across Japan — redundant infrastructure, multi-camera direction, and dedicated technical monitoring for events of any scale.'),
  ('ba8cc7aa-7d75-5fbe-8b21-46465f5c0d8f', 'led-solutions', 'technical', 'LED Solutions', 'Indoor and outdoor LED wall design, rigging, and content playback engineered to pitch and viewing distance.', 'LED that''s specified to the room, not just rented off a shelf.', ARRAY['The wrong pixel pitch or panel size is one of the most common — and most visible — mistakes in event production. We specify LED to your actual viewing distance, content, and venue rather than defaulting to whatever''s available.', 'From fine-pitch indoor walls for close-viewing stage backdrops to weatherproof outdoor screens for ceremonies and activations, we handle rigging, calibration, and content playback as one integrated service.']::text[], ARRAY['Pixel-pitch specification matched to viewing distance', 'Indoor and outdoor, weatherproof LED systems', 'Curved, angled, and custom-shape LED configurations', 'Rigging engineering and structural load sign-off', 'Content playback and media server operation', 'On-site calibration and color matching']::text[], '[{"title":"Viewing & Content Review","description":"We assess sightlines, viewing distance, and content type to specify the right pitch."},{"title":"Rigging Design","description":"Structural rigging engineered and load-checked against venue and hardware limits."},{"title":"Build & Calibration","description":"Panels rigged, calibrated, and color-matched before doors open."},{"title":"Live Operation","description":"Media server and playback operated live by our technicians."}]'::jsonb, ARRAY['Stage backdrops and keynote screens', 'Exhibition and booth walls', 'Outdoor ceremonies and activations', 'Broadcast and camera-facing displays']::text[], 'LED Wall Rental & Solutions in Japan | TOTAL MEDIA', 'Indoor and outdoor LED wall solutions across Japan — pitch specification, rigging engineering, and live content playback for stages, booths, and outdoor events.'),
  ('70f08b4c-70d8-5464-aa1d-48e61e6b7fcb', 'audio-solutions', 'technical', 'Audio Solutions', 'Line array PA, digital mixing, and interpretation audio designed to room acoustics and program type.', 'Audio should disappear — you only notice it when it''s wrong.', ARRAY['Good audio is invisible: even coverage, no feedback, clean intelligibility for speech and music alike. We design PA and mixing systems to the room''s acoustics and the specific program — a keynote and a live band need genuinely different systems, not the same rig turned up or down.', 'We also handle the audio infrastructure that''s easy to overlook until it fails: interpretation channels, wireless microphone coordination in RF-dense venues, and clean feeds for broadcast and recording.']::text[], ARRAY['Line array PA design matched to room acoustics', 'Digital mixing and monitor systems', 'Wireless microphone RF coordination', 'Simultaneous interpretation audio distribution', 'Broadcast and recording audio feeds', 'Live sound engineering and mixing']::text[], '[{"title":"Room & Program Assessment","description":"We assess room acoustics and program type before specifying the system."},{"title":"System Design","description":"PA, mixing, and RF plan designed to avoid coverage gaps and interference."},{"title":"Build & Tuning","description":"System installed and acoustically tuned to the specific room."},{"title":"Live Mixing","description":"A dedicated engineer mixes live rather than leaving the system unattended."}]'::jsonb, ARRAY['Conference and keynote audio', 'Multilingual events with interpretation', 'Live music and entertainment programs', 'Broadcast and recorded events']::text[], 'Event Audio Systems & Solutions in Japan | TOTAL MEDIA', 'Line array PA, digital mixing, and interpretation audio solutions across Japan, designed to room acoustics and engineered by live audio technicians.'),
  ('f487f21a-5a5b-5ec0-beb5-16d8cc0bf010', 'lighting-solutions', 'technical', 'Lighting Solutions', 'Stage, architectural, and ambient lighting design programmed to support the moment, not just illuminate it.', 'Lighting sets the tone before a single word is spoken.', ARRAY['Lighting is the fastest way to signal formality, energy, or intimacy to a room before anyone speaks — and one of the most under-specified elements in standard event packages. We design lighting as a storytelling tool, not a default wash.', 'Our lighting designers program cues around your run-of-show, so transitions between segments — keynote to panel, presentation to reveal — are marked by light, not just a change of slide.']::text[], ARRAY['Stage and keynote lighting design', 'Moving light and architectural wash programming', 'Cue-based lighting synced to run-of-show', 'Camera-matched lighting for broadcast and streaming', 'Ambient and wayfinding lighting for venue spaces', 'Console programming and live operation']::text[], '[{"title":"Mood & Cue Planning","description":"We map lighting cues to your run-of-show and the tone each segment needs."},{"title":"Design & Fixture Plan","description":"Fixture selection and rigging plan built to the venue and program."},{"title":"Programming","description":"Cues programmed and tested against the actual run-of-show before doors open."},{"title":"Live Operation","description":"A lighting operator runs the cues live, adjusting in real time as needed."}]'::jsonb, ARRAY['Keynote and stage lighting', 'Product reveal and launch lighting', 'Award ceremony presentation lighting', 'Ambient venue and gala lighting']::text[], 'Event Lighting Design & Solutions in Japan | TOTAL MEDIA', 'Stage, architectural, and ambient lighting solutions across Japan — cue-based design programmed to your run-of-show by professional lighting operators.'),
  ('3f2d7214-e0d7-557b-b306-74f2c02e2e76', 'stage-production', 'technical', 'Stage Production', 'Modular staging, set construction, and structural rigging engineered to venue and program requirements.', 'The stage is the one piece of infrastructure everything else stands on.', ARRAY['Every other technical element — LED, lighting, audio, cameras — depends on the stage being structurally sound, correctly sized, and built to the venue''s actual constraints. We treat staging as engineering first, aesthetics second, though we don''t compromise on either.', 'We build modular stage decking, custom set elements, and rigging systems sized to your program, from a simple presentation platform to a multi-level set with integrated LED and rigging.']::text[], ARRAY['Modular stage decking and riser systems', 'Custom set design and construction', 'Structural rigging engineered to venue load limits', 'Multi-level and runway stage configurations', 'Backstage and quick-change infrastructure', 'Fast build/strike crews for compressed schedules']::text[], '[{"title":"Venue & Load Assessment","description":"We confirm venue floor load, rigging points, and access before design."},{"title":"Structural Design","description":"Stage and set engineered to program requirements and signed off structurally."},{"title":"Build","description":"Coordinated crews build to a schedule matched to your load-in window."},{"title":"Strike","description":"Structured teardown sequenced to venue move-out requirements."}]'::jsonb, ARRAY['Keynote and conference staging', 'Award ceremony and gala staging', 'Product launch sets', 'Trade show main stages']::text[], 'Stage Production & Set Construction in Japan | TOTAL MEDIA', 'Modular staging, custom set construction, and structural rigging across Japan, engineered to venue load limits and built for fast build/strike windows.'),
  ('26f219a2-c569-5329-acee-51c3f3e0d92d', 'technical-production', 'technical', 'Technical Production', 'Integrated technical direction across LED, audio, lighting, staging, and camera systems as one coordinated discipline.', 'Someone has to own the whole technical picture. That''s this service.', ARRAY['Most technical failures at events happen at the seams between disciplines — lighting that clashes with camera exposure, audio that isn''t synced with video delay, rigging that wasn''t coordinated between the LED and lighting teams. Technical production is the discipline of owning those seams.', 'We provide a technical director who coordinates every system — LED, audio, lighting, staging, cameras — as one integrated build, backed by our full equipment inventory and specialist crews for each discipline.']::text[], ARRAY['Single technical director owning the full production', 'Cross-discipline coordination (LED, audio, lighting, staging, camera)', 'Power distribution and infrastructure planning', 'Technical rehearsal and cue integration across systems', 'On-site technical troubleshooting and contingency management', 'Post-event technical reporting']::text[], '[{"title":"Technical Scoping","description":"We map every technical discipline your event requires into one plan."},{"title":"Integrated Design","description":"Systems designed together so cues, power, and rigging align across disciplines."},{"title":"Full Technical Rehearsal","description":"Every system tested together, not just individually."},{"title":"Live Technical Direction","description":"One technical director owns execution and contingency in real time."}]'::jsonb, ARRAY['Multi-discipline productions of any format', 'Events with complex rigging or power needs', 'Broadcast-integrated live events', 'Clients who want one technical point of contact']::text[], 'Technical Event Production Services in Japan | TOTAL MEDIA', 'Integrated technical production across Japan — one technical director coordinating LED, audio, lighting, staging, and camera systems as a single build.'),
  ('9f406ce5-9fab-567b-b8ac-9248d7f78b81', 'event-consultation', 'technical', 'Event Consultation', 'Independent technical and production consultation for teams planning events without in-house AV expertise.', 'Sometimes the most useful thing we can do is advise before you commit.', ARRAY['Not every engagement needs to start with a full production build. When a team is early in planning — evaluating a venue, sizing a budget, or scoping what "hybrid" would actually require — we offer standalone consultation to get the technical picture right before commitments are made.', 'This includes venue technical assessments, budget scoping, RFP and vendor-brief support, and second-opinion reviews of technical plans built by another vendor or an internal team.']::text[], ARRAY['Venue technical assessment and site walkthroughs', 'Budget scoping and technical feasibility review', 'RFP and vendor-brief technical input', 'Second-opinion review of existing technical plans', 'Format guidance (in-person, hybrid, or virtual)', 'Vendor coordination advice for multi-vendor events']::text[], '[{"title":"Discovery Call","description":"We understand your event, constraints, and what decision you''re trying to make."},{"title":"Assessment","description":"Venue review, budget scoping, or plan review, depending on your need."},{"title":"Written Recommendation","description":"A clear, actionable recommendation — not a sales pitch for our own services."},{"title":"Optional Follow-Through","description":"If you''d like us to execute, the consultation becomes the basis of the proposal."}]'::jsonb, ARRAY['Teams planning their first hybrid event', 'Internal teams without dedicated AV staff', 'RFP and vendor selection processes', 'Second opinions on existing technical plans']::text[], 'Event Technical Consultation Services in Japan | TOTAL MEDIA', 'Independent event technical consultation across Japan — venue assessments, budget scoping, and second-opinion reviews for teams planning without in-house AV expertise.');
