insert into solutions (id, slug, name, short_description, hero_statement, overview, highlights, seo_title, seo_description) values
  ('ec4f926e-1554-5dd0-8f3a-99da99554fa2', 'hybrid-virtual-solutions', 'Hybrid & Virtual Event Solutions', 'A packaged approach to running in-room and remote audiences as one production, from platform selection through live broadcast direction.', 'For organizations whose audience is never entirely in one room.', ARRAY['Hybrid and virtual formats aren''t a single service — they combine event planning, technical production, live streaming, and often interpretation into one dependency chain, where a gap in any part shows up live, in front of your audience.', 'This solution bundles the disciplines that make hybrid and virtual events reliable: dual-audience content design, redundant streaming infrastructure, and a technical director whose sole responsibility is the broadcast, working alongside — not instead of — your in-room production team.']::text[], '[{"title":"Dual-audience design","description":"Content and camera plans built for the room and the stream from day one, not adapted afterward."},{"title":"Redundant infrastructure","description":"Dual internet circuits and backup encoding paths as standard, not an upsell."},{"title":"Independent broadcast direction","description":"A dedicated technical director for the stream, separate from in-room stage management."},{"title":"Interpretation-ready","description":"Simultaneous interpretation channels built into the broadcast for in-room and remote audiences alike."}]'::jsonb, 'Hybrid & Virtual Event Solutions in Japan | TOTAL MEDIA', 'A packaged hybrid and virtual event solution across Japan — dual-audience design, redundant streaming, and independent broadcast direction.'),
  ('625b1493-95e7-568e-a762-877e13e77a54', 'large-format-visual-solutions', 'Large-Format Visual & LED Solutions', 'LED, projection, and lighting bundled as one visual system, specified together instead of sourced separately.', 'For events where the visual scale is the point.', ARRAY['Large-format visual moments — a keynote backdrop, an exhibition centerpiece, an outdoor ceremony screen — depend on LED, lighting, and often projection working as one coordinated system, not three separately rented components pointed at the same stage.', 'This solution combines pitch-specified LED, cue-based lighting design, and rigging engineering into a single visual production plan, so color, brightness, and cueing are consistent across every element the audience sees at once.']::text[], '[{"title":"One visual system","description":"LED, lighting, and projection specified and calibrated together, not independently."},{"title":"Rigging engineered as one build","description":"Structural load calculated across every visual element sharing the same truss."},{"title":"Content and cue integration","description":"Media playback and lighting cues synced to the same run-of-show."},{"title":"Indoor and outdoor capable","description":"Weatherproof options for ceremonies and activations outside the venue walls."}]'::jsonb, 'Large-Format LED & Visual Solutions in Japan | TOTAL MEDIA', 'Large-format visual solutions across Japan — LED, lighting, and rigging engineered together as one coordinated visual system.'),
  ('b18d314b-00be-5b3a-b0ed-0d7302b3cf27', 'broadcast-streaming-solutions', 'Broadcast & Streaming Solutions', 'Multi-camera broadcast production and redundant live streaming bundled for events that need television-grade output.', 'For events that are being watched as much as they''re being attended.', ARRAY['Award ceremonies, product reveals, and press events increasingly live and die by what the camera captures, not just what happens in the room. This solution bundles multi-camera direction, broadcast-grade audio, and redundant streaming into one production discipline.', 'We handle vision switching, live graphics, and multi-language audio channels alongside the underlying streaming infrastructure, so the broadcast output is a directed production, not a static camera pointed at a stage.']::text[], '[{"title":"Multi-camera direction","description":"Vision switching and shot composition handled by broadcast-trained camera operators."},{"title":"Redundant delivery","description":"Dual circuits and backup encoding as standard for anything broadcast-critical."},{"title":"Live graphics and overlays","description":"Lower-thirds, branding, and multi-language captions integrated live."},{"title":"Platform-agnostic","description":"Delivered to the platform your audience already uses, not a proprietary one."}]'::jsonb, 'Broadcast & Live Streaming Solutions in Japan | TOTAL MEDIA', 'Broadcast and streaming solutions across Japan — multi-camera direction, redundant delivery, and live graphics for television-grade event output.'),
  ('d8c6ff79-d570-599f-958c-80a307564bc0', 'full-service-technical-solutions', 'Full-Service Technical Production Solutions', 'Every technical discipline — LED, audio, lighting, staging, rigging, cameras — under a single technical director.', 'For events large enough that coordination is the actual risk.', ARRAY['At a certain scale, the biggest risk to an event isn''t any single technical system — it''s the coordination between them. Power allocated for lighting that clashes with LED draw. Camera positions that block a sightline the audio team already claimed. Rigging points double-booked between two vendors.', 'This solution puts every technical discipline under one technical director and one integrated build plan, backed by our full equipment inventory rather than subcontracted pieces, so the seams between systems are our responsibility, not yours to manage.']::text[], '[{"title":"One technical director","description":"A single point of accountability across every technical discipline on-site."},{"title":"Integrated build plan","description":"Power, rigging, and cueing planned together across LED, audio, lighting, and staging."},{"title":"Full in-house inventory","description":"Equipment drawn from our own catalogue, not subcontracted piecemeal."},{"title":"Contingency-ready","description":"Backup systems and a technical team empowered to problem-solve live."}]'::jsonb, 'Full-Service Technical Production Solutions in Japan | TOTAL MEDIA', 'Full-service technical production solutions across Japan — every discipline, from LED to rigging to cameras, under one technical director.');
