insert into equipment_items (id, slug, category_id, name, summary, description, specs, applications, availability, visual_seed) values
  ('a3c5ed3f-2c52-5849-8bee-f913a7ee9a9f', 'indoor-led-p1-9-fine-pitch', '41e7596a-a20d-579c-bf8f-97e9d4d68f90', 'P1.9 Fine-Pitch Indoor LED', 'Ultra-fine pitch panel for close-viewing stage backdrops and broadcast-facing displays.', 'Our finest indoor pitch, specified for environments where the audience or camera sits close to the wall — broadcast backdrops, boardroom displays, and stage content viewed from the front rows. Seamless cabinet joins hold up under camera close-ups.', '[{"label":"Pixel Pitch","value":"1.9mm"},{"label":"Brightness","value":"800 nits"},{"label":"Cabinet Size","value":"500 x 500mm"},{"label":"Refresh Rate","value":"3840Hz"},{"label":"Recommended Viewing Distance","value":"2m+"}]'::jsonb, ARRAY['Broadcast backdrops', 'Boardroom and briefing room displays', 'Close-viewing stage content']::text[], 'limited', 'indoor-led-p1-9-fine-pitch'),
  ('729fbb96-35b9-545b-8b52-e18fc25bb287', 'indoor-led-p2-6-standard', '41e7596a-a20d-579c-bf8f-97e9d4d68f90', 'P2.6 Indoor LED Panel', 'Our most-deployed indoor pitch, balancing image quality and cost for standard stage backdrops.', 'The standard specification for keynote and conference stage backdrops, where viewing distance is typically beyond three meters. Lightweight cabinets and quick-lock rigging keep build time down without compromising image quality.', '[{"label":"Pixel Pitch","value":"2.6mm"},{"label":"Brightness","value":"1000 nits"},{"label":"Cabinet Size","value":"500 x 500mm"},{"label":"Refresh Rate","value":"3840Hz"},{"label":"Recommended Viewing Distance","value":"3m+"}]'::jsonb, ARRAY['Keynote and conference backdrops', 'Exhibition booth walls', 'Product launch stages']::text[], 'in-stock', 'indoor-led-p2-6-standard'),
  ('1917e4e9-aa8d-5102-836e-a404d72dd5b8', 'indoor-led-p3-9-rental', '41e7596a-a20d-579c-bf8f-97e9d4d68f90', 'P3.9 Indoor Rental Panel', 'High-volume rental panel for large-format indoor walls where distance allows a wider pitch.', 'Specified for large indoor walls — exhibition hall centerpieces, gala backdrops — where viewing distance is generous enough that a wider pitch delivers the same perceived quality at lower cost and faster build time.', '[{"label":"Pixel Pitch","value":"3.9mm"},{"label":"Brightness","value":"1200 nits"},{"label":"Cabinet Size","value":"500 x 1000mm"},{"label":"Refresh Rate","value":"1920Hz"},{"label":"Recommended Viewing Distance","value":"4m+"}]'::jsonb, ARRAY['Large exhibition hall walls', 'Gala and ceremony backdrops', 'Multi-panel curved configurations']::text[], 'in-stock', 'indoor-led-p3-9-rental'),
  ('f4469a5b-aa2c-59be-9caf-c3b06829059b', 'outdoor-led-p3-9-weatherproof', '0845907f-81e5-58bb-8242-f7d29c19ab63', 'P3.9 Outdoor Weatherproof Panel', 'IP65-rated outdoor panel for daylight-visible ceremonies and activations.', 'Sealed for weather and specified for daylight visibility, this panel is our standard for outdoor ceremonies, activations, and stages where the screen needs to hold up against sun, wind, and light rain without a service interruption.', '[{"label":"Pixel Pitch","value":"3.9mm"},{"label":"Brightness","value":"5500 nits"},{"label":"IP Rating","value":"IP65 (front & rear)"},{"label":"Cabinet Size","value":"500 x 500mm"},{"label":"Wind Load Rating","value":"Engineered per structural review"}]'::jsonb, ARRAY['Outdoor ceremonies', 'Brand activations', 'Festival and public event stages']::text[], 'in-stock', 'outdoor-led-p3-9-weatherproof'),
  ('b064f365-0207-51cf-a965-cc0fde06a0b4', 'outdoor-led-p4-8-screen', '0845907f-81e5-58bb-8242-f7d29c19ab63', 'P4.8 Outdoor LED Screen', 'Large-format outdoor screen system for distant viewing and high-brightness daylight conditions.', 'Built for large outdoor footprints where viewing distance runs long — outdoor ceremony backdrops, IMAG screens for large audiences, and public-facing brand walls that need to compete with direct sunlight.', '[{"label":"Pixel Pitch","value":"4.8mm"},{"label":"Brightness","value":"6000 nits"},{"label":"IP Rating","value":"IP65 (front & rear)"},{"label":"Cabinet Size","value":"500 x 1000mm"},{"label":"Recommended Viewing Distance","value":"6m+"}]'::jsonb, ARRAY['Large outdoor ceremonies', 'IMAG screens for large audiences', 'Outdoor brand activations']::text[], 'in-stock', 'outdoor-led-p4-8-screen'),
  ('8d7c335e-1df1-5a2c-adc4-88414cd6cc0a', 'outdoor-led-p6-6-wall', '0845907f-81e5-58bb-8242-f7d29c19ab63', 'P6.6 Outdoor LED Wall', 'Long-throw outdoor wall for stadium-scale distance and rapid multi-panel deployment.', 'The widest outdoor pitch in our inventory, deployed for very large audiences and long viewing distances where rapid multi-panel build time matters as much as brightness — outdoor festivals, large ceremonies, and public gatherings.', '[{"label":"Pixel Pitch","value":"6.6mm"},{"label":"Brightness","value":"6500 nits"},{"label":"IP Rating","value":"IP65 (front & rear)"},{"label":"Cabinet Size","value":"500 x 1000mm"},{"label":"Recommended Viewing Distance","value":"10m+"}]'::jsonb, ARRAY['Stadium-scale outdoor events', 'Large public ceremonies', 'Festival main stage screens']::text[], 'limited', 'outdoor-led-p6-6-wall'),
  ('4117657f-68e0-57d4-bbef-48163c040cad', 'audio-line-array-pa', '64226ae0-a90f-5570-8c0a-9aa6662e254b', 'Line Array PA System', 'Scalable line array system for even coverage across conference and ceremony spaces.', 'Our primary PA system for mid-to-large rooms, configured per event to deliver even coverage front to back without the hot spots and dead zones of point-source speakers. Scales from a single hang to full stereo arrays for larger halls.', '[{"label":"Configuration","value":"Modular line array, scalable per room"},{"label":"Frequency Response","value":"38Hz – 20kHz"},{"label":"Max SPL","value":"138dB (array dependent)"},{"label":"Rigging","value":"Flown or ground-stacked"}]'::jsonb, ARRAY['Conference and keynote halls', 'Award ceremonies and galas', 'Multi-purpose venue spaces']::text[], 'in-stock', 'audio-line-array-pa'),
  ('a64f73f2-5b83-5391-9f98-a6f563da321a', 'audio-digital-mixing-console', '64226ae0-a90f-5570-8c0a-9aa6662e254b', 'Digital Mixing Console', 'Multi-channel digital console for live mixing, monitor mixes, and broadcast feeds.', 'A digital console platform operated by a dedicated engineer for every event, supporting simultaneous front-of-house mixing, monitor mixes for presenters, and a clean, separate feed for broadcast or recording.', '[{"label":"Channel Count","value":"Up to 64 input channels"},{"label":"Outputs","value":"FOH, monitor, and broadcast feeds simultaneously"},{"label":"Redundancy","value":"Dual power supply, backup console option"},{"label":"Recording","value":"Multi-track session recording available"}]'::jsonb, ARRAY['Live event mixing', 'Multi-language interpretation routing', 'Broadcast and recording feeds']::text[], 'in-stock', 'audio-digital-mixing-console'),
  ('b0343dac-8c67-5d6a-9d82-6aa1885843b6', 'audio-wireless-microphone-system', '64226ae0-a90f-5570-8c0a-9aa6662e254b', 'Wireless Microphone System', 'RF-coordinated wireless handheld, lavalier, and headset microphones for speakers and panels.', 'Wireless microphone systems coordinated channel-by-channel against the venue''s RF environment, avoiding the dropouts and interference common in dense urban venues and multi-vendor events sharing the same spectrum.', '[{"label":"Channel Types","value":"Handheld, lavalier, headset"},{"label":"RF Coordination","value":"Frequency-coordinated per venue"},{"label":"Range","value":"Up to 100m line-of-sight"},{"label":"Battery Management","value":"Rechargeable with on-site charging station"}]'::jsonb, ARRAY['Panel discussions and Q&A', 'Keynote presentations', 'Award ceremony presenter mics']::text[], 'in-stock', 'audio-wireless-microphone-system'),
  ('c83bc47a-f118-5920-9daa-a2931d0cf679', 'lighting-moving-head-spot', 'dc50a406-72a2-5a43-92ad-f187fa557974', 'Moving Head Spot Fixture', 'Programmable moving spot fixture for stage lighting, gobos, and dynamic cueing.', 'Our primary fixture for stage and keynote lighting design, capable of precise gobo projection, color changes, and cue-based movement synced to the run-of-show — used for everything from subtle key lighting to full production cueing.', '[{"label":"Output","value":"800W LED engine"},{"label":"Color","value":"Full CMY + color wheel"},{"label":"Gobo Wheels","value":"2 rotating + 1 fixed"},{"label":"Control Protocol","value":"DMX / RDM"}]'::jsonb, ARRAY['Stage and keynote lighting', 'Product reveal cueing', 'Award ceremony presentation lighting']::text[], 'in-stock', 'lighting-moving-head-spot'),
  ('f0365306-4d0e-5923-afd4-eb8fa81e559d', 'lighting-led-wash', 'dc50a406-72a2-5a43-92ad-f187fa557974', 'LED Wash Fixture', 'Wide-beam LED wash for ambient stage color and architectural venue lighting.', 'Provides the broad, even color wash that grounds a stage or venue lighting design — set behind or beside moving spots for depth, or used on its own for ambient gala and reception lighting.', '[{"label":"Output","value":"300W RGBAL LED array"},{"label":"Beam Angle","value":"10°–60° zoom"},{"label":"Color","value":"Full RGBAL mixing"},{"label":"Control Protocol","value":"DMX / RDM"}]'::jsonb, ARRAY['Ambient stage wash', 'Architectural venue lighting', 'Gala and reception lighting']::text[], 'in-stock', 'lighting-led-wash'),
  ('be3790c1-53b8-5482-b2d3-0b13e2cda6f4', 'lighting-console', 'dc50a406-72a2-5a43-92ad-f187fa557974', 'Lighting Console', 'Cue-based lighting control console operated live by a dedicated programmer.', 'The control hub for every lighting design we build — cues are programmed against your run-of-show in advance and operated live by a lighting technician who can adjust in real time as the event actually unfolds.', '[{"label":"Control Capacity","value":"Up to 4096 DMX channels"},{"label":"Cue Storage","value":"Unlimited programmable cues"},{"label":"Backup","value":"Redundant console failover available"},{"label":"Networking","value":"Art-Net / sACN"}]'::jsonb, ARRAY['Cue-based stage lighting', 'Multi-fixture architectural control', 'Broadcast-synced lighting programs']::text[], 'in-stock', 'lighting-console'),
  ('fba744bb-2f0b-5b8a-84ef-43507cc7dc31', 'stage-modular-deck', '7a6ecd4f-fec0-5175-9515-788442c38c3c', 'Modular Stage Deck System', 'Adjustable-height modular decking for stages of virtually any footprint.', 'Our standard stage decking system, configurable in height, footprint, and shape to match venue and program requirements — from a simple presentation platform to a full multi-level production stage.', '[{"label":"Deck Size","value":"2m x 1m modules"},{"label":"Height Range","value":"0.2m – 2.4m adjustable"},{"label":"Load Rating","value":"750kg/m² distributed"},{"label":"Surface","value":"Non-slip, broadcast-black finish"}]'::jsonb, ARRAY['Keynote and conference stages', 'Award ceremony staging', 'Multi-level product launch sets']::text[], 'in-stock', 'stage-modular-deck'),
  ('72fe5674-ea2d-5841-a115-c886aa97caeb', 'stage-riser-platform', '7a6ecd4f-fec0-5175-9515-788442c38c3c', 'Stage Riser Platform', 'Freestanding riser platforms for panel discussions, VIP seating, and camera positions.', 'Compact, freestanding platforms used to elevate panel seating, VIP tables, or camera positions above the main floor level — quick to deploy without the full structural planning a main stage requires.', '[{"label":"Platform Size","value":"2m x 1m, single or stacked"},{"label":"Height Options","value":"0.2m, 0.4m, 0.6m"},{"label":"Load Rating","value":"500kg/m² distributed"},{"label":"Setup Time","value":"Under 30 minutes per unit"}]'::jsonb, ARRAY['Panel discussion seating', 'VIP and head-table elevation', 'Camera platform positions']::text[], 'in-stock', 'stage-riser-platform'),
  ('1ab1f41b-d61c-5ebe-a337-189743cda51f', 'stage-runway', '7a6ecd4f-fec0-5175-9515-788442c38c3c', 'Runway / Catwalk Stage', 'Extended runway staging for product reveals, fashion-format presentations, and processional formats.', 'Extended, narrow-format staging for events where movement through the space is part of the presentation — product reveal walks, fashion-format shows, and award ceremony processional entrances.', '[{"label":"Standard Length","value":"8m, extendable in 2m sections"},{"label":"Width","value":"1.2m standard, 1.8m available"},{"label":"Height","value":"0.4m – 0.8m"},{"label":"Surface","value":"Non-slip, camera-matte finish"}]'::jsonb, ARRAY['Product reveal walks', 'Fashion-format presentations', 'Award ceremony processional entrances']::text[], 'made-to-order', 'stage-runway'),
  ('1d7c9792-ba5b-5949-90e3-ae617fa28a84', 'truss-box-ground-support', '40c82f4b-eeba-599e-9ac8-1835f24df6fd', 'Box Truss Ground Support', 'Self-supporting ground-based truss for LED, lighting, and speaker arrays without venue rigging points.', 'Used when a venue has no overhead rigging points, or when structural sign-off favors a ground-supported solution — engineered box truss towers and spans that carry LED, lighting, and speaker loads independently.', '[{"label":"Truss Profile","value":"400mm and 520mm box truss"},{"label":"Max Span","value":"Engineered per load and configuration"},{"label":"Load Capacity","value":"Calculated per structural review"},{"label":"Base Options","value":"Weighted base plates or outrigger stabilizers"}]'::jsonb, ARRAY['Venues without overhead rigging', 'Outdoor stage structures', 'LED and speaker support towers']::text[], 'in-stock', 'truss-box-ground-support'),
  ('4878dde3-e689-5ffd-9182-78a55e1c69aa', 'truss-motorized-hoist', '40c82f4b-eeba-599e-9ac8-1835f24df6fd', 'Motorized Chain Hoist', 'Motorized rigging hoists for flown LED, lighting, and speaker arrays with precise height control.', 'Motorized hoists used for flying LED walls, lighting trusses, and line array speakers from venue rigging points, with precision height control for load-in adjustments and safe, controlled strike.', '[{"label":"Load Capacity","value":"500kg – 1000kg per hoist"},{"label":"Control","value":"Synchronized multi-hoist control system"},{"label":"Safety","value":"Certified load limiters and secondary safety cables"},{"label":"Speed","value":"Variable speed with fine adjustment"}]'::jsonb, ARRAY['Flown LED walls', 'Flown lighting trusses', 'Flown line array speaker systems']::text[], 'limited', 'truss-motorized-hoist'),
  ('d39213f0-a1f3-5ef4-9fff-fde3119f7754', 'truss-tower-system', '40c82f4b-eeba-599e-9ac8-1835f24df6fd', 'Truss Tower System', 'Vertical truss towers for lighting positions, speaker delays, and outdoor screen support.', 'Freestanding vertical towers used to position lighting fixtures, delay speakers, or support outdoor LED screens at height, independent of the main stage structure.', '[{"label":"Height Range","value":"3m – 12m, sectional"},{"label":"Base Footprint","value":"Weighted or guy-wired, per site conditions"},{"label":"Load Capacity","value":"Calculated per fixture load"},{"label":"Wind Rating","value":"Engineered for outdoor deployment"}]'::jsonb, ARRAY['Outdoor lighting towers', 'Delay speaker positions', 'Outdoor LED screen support']::text[], 'in-stock', 'truss-tower-system'),
  ('4cf846cc-e202-5507-87e7-5ed58cb8bcf8', 'projector-20000-lumen-laser', '7b444a28-4071-5315-ae17-0ebf37598392', '20,000 Lumen Laser Projector', 'High-lumen laser projector for large-venue backdrops and projection mapping.', 'Our highest-output projector, specified for large venues with high ambient light, wide-format screens, or projection mapping onto set pieces and architecture that demands consistent brightness across an uneven surface.', '[{"label":"Brightness","value":"20,000 lumens"},{"label":"Resolution","value":"4K UHD (3840 x 2160)"},{"label":"Light Source","value":"Laser phosphor, 20,000hr rated life"},{"label":"Lens Options","value":"Short-throw to long-throw available"}]'::jsonb, ARRAY['Large-venue stage backdrops', 'Projection mapping on set pieces', 'High-ambient-light environments']::text[], 'limited', 'projector-20000-lumen-laser'),
  ('c6a01088-ab0f-5021-b70b-f2cc78e53982', 'projector-10000-lumen-laser', '7b444a28-4071-5315-ae17-0ebf37598392', '10,000 Lumen Laser Projector', 'Mid-output laser projector for standard conference and presentation environments.', 'A versatile mid-output projector suited to standard conference rooms and presentation stages with controlled ambient light — our most frequently deployed unit for content and presentation projection.', '[{"label":"Brightness","value":"10,000 lumens"},{"label":"Resolution","value":"4K UHD (3840 x 2160)"},{"label":"Light Source","value":"Laser phosphor, 20,000hr rated life"},{"label":"Lens Options","value":"Standard zoom lens included"}]'::jsonb, ARRAY['Conference room presentations', 'Content and slide projection', 'Mid-size venue backdrops']::text[], 'in-stock', 'projector-10000-lumen-laser'),
  ('e0fbe30c-c709-55c9-9f3d-928ab06c3f85', 'projector-short-throw', '7b444a28-4071-5315-ae17-0ebf37598392', 'Short-Throw Projector', 'Short-throw unit for tight venue spaces and stage-front projection without a long lens path.', 'Deployed where floor space or ceiling height limits a standard lens throw distance — booth environments, tight stage-front content projection, or spaces where a projector stand can''t sit far from the screen.', '[{"label":"Brightness","value":"6,500 lumens"},{"label":"Resolution","value":"WUXGA (1920 x 1200)"},{"label":"Throw Ratio","value":"0.38:1"},{"label":"Light Source","value":"Laser phosphor"}]'::jsonb, ARRAY['Exhibition booth projection', 'Tight-space stage-front content', 'Low-ceiling venue environments']::text[], 'in-stock', 'projector-short-throw'),
  ('cef887b1-0ecd-5a80-9ff5-2c9668781351', 'displays-55-inch-signage', '9eaef7be-aa6c-5a6f-ac49-80e3a8b2e8cb', '55" Digital Signage Display', 'Freestanding or mounted digital signage display for wayfinding, registration, and information points.', 'Our standard signage display for registration desks, wayfinding points, and information stations — supplied with a floor stand or wall mount and content playback support.', '[{"label":"Screen Size","value":"55\""},{"label":"Resolution","value":"4K UHD"},{"label":"Brightness","value":"500 nits"},{"label":"Mounting","value":"Floor stand or wall mount"}]'::jsonb, ARRAY['Registration and welcome desks', 'Wayfinding and directory signage', 'Sponsor and agenda displays']::text[], 'in-stock', 'displays-55-inch-signage'),
  ('e5d993e4-f0be-58ae-a55f-adcd7294cd95', 'displays-touch-kiosk', '9eaef7be-aa6c-5a6f-ac49-80e3a8b2e8cb', 'Freestanding Touch Kiosk', 'Interactive touchscreen kiosk for exhibition engagement and self-service registration.', 'An interactive kiosk used for exhibition booth engagement, self-service check-in, and interactive content — deployed standalone or networked across a show floor.', '[{"label":"Screen Size","value":"32\" or 43\" touch display"},{"label":"Touch Technology","value":"Capacitive multi-touch"},{"label":"Connectivity","value":"Wi-Fi / Ethernet, networkable"},{"label":"Housing","value":"Freestanding, branded wrap available"}]'::jsonb, ARRAY['Exhibition booth engagement', 'Self-service check-in', 'Interactive product showcases']::text[], 'in-stock', 'displays-touch-kiosk'),
  ('76255dff-cbb3-5565-a584-33bda8352827', 'displays-video-wall', '9eaef7be-aa6c-5a6f-ac49-80e3a8b2e8cb', 'Video Wall Display', 'Modular LCD video wall for a screen-based (non-LED) large-format display option.', 'A modular LCD video wall alternative to LED for indoor environments where a screen-based large display is preferred — content-rich exhibition centerpieces and lobby installations.', '[{"label":"Configuration","value":"2x2 to 5x5 modular array"},{"label":"Bezel Width","value":"3.5mm ultra-narrow"},{"label":"Resolution","value":"4K UHD per module, tiled"},{"label":"Mounting","value":"Freestanding frame or wall-mounted"}]'::jsonb, ARRAY['Exhibition centerpiece displays', 'Lobby and reception installations', 'Content-rich indoor walls']::text[], 'in-stock', 'displays-video-wall'),
  ('38ad82e0-0b2b-59a6-be0a-a53df1eaa07a', 'camera-ptz-system', '399b2066-bb90-5ef1-bc1b-ae48c5ff84b6', 'PTZ Camera System', 'Remote pan-tilt-zoom cameras for unobtrusive multi-angle coverage without a dedicated operator per camera.', 'Remotely controlled PTZ cameras used to add coverage angles — audience shots, wide stage shots, panel close-ups — without staffing a camera operator at every position. Controlled from a central vision panel.', '[{"label":"Output","value":"4K UHD / 1080p60"},{"label":"Zoom","value":"20x optical"},{"label":"Control","value":"Centralized PTZ control panel"},{"label":"Mounting","value":"Ceiling, wall, or tripod mount"}]'::jsonb, ARRAY['Panel and audience coverage', 'Unobtrusive multi-angle shots', 'Hybrid and streaming productions']::text[], 'in-stock', 'camera-ptz-system'),
  ('f0ba6108-3ec9-509c-8bae-d217e30c63d3', 'camera-broadcast-package', '399b2066-bb90-5ef1-bc1b-ae48c5ff84b6', 'Broadcast Camera Package', 'Operator-staffed broadcast cameras for award ceremonies, keynotes, and directed multi-camera productions.', 'Full broadcast camera packages with dedicated operators, used for productions where composed, directed shots matter — award ceremonies, keynote coverage, and any event being recorded or streamed as a produced broadcast.', '[{"label":"Output","value":"4K UHD broadcast cameras"},{"label":"Crew","value":"Staffed by trained camera operators"},{"label":"Lens Kits","value":"Zoom and prime lens options"},{"label":"Signal","value":"SDI/fiber transmission to vision switcher"}]'::jsonb, ARRAY['Award ceremony coverage', 'Keynote and stage broadcast', 'Directed multi-camera productions']::text[], 'in-stock', 'camera-broadcast-package'),
  ('5ba21bbd-382e-576f-a0f6-d5a4b73da66c', 'camera-vision-switcher-kit', '399b2066-bb90-5ef1-bc1b-ae48c5ff84b6', 'Vision Switcher & Streaming Kit', 'Multi-camera vision switching and encoding kit for live production and streaming output.', 'The production hub for multi-camera events — switching between camera feeds, integrating graphics and lower-thirds, and encoding the final program for live streaming or broadcast delivery.', '[{"label":"Inputs","value":"Up to 8 camera/source inputs"},{"label":"Output","value":"Multi-platform streaming encode + program feed"},{"label":"Graphics","value":"Live lower-thirds and overlay integration"},{"label":"Redundancy","value":"Backup encoder and dual internet path"}]'::jsonb, ARRAY['Live streaming production', 'Multi-camera event direction', 'Hybrid event broadcast']::text[], 'in-stock', 'camera-vision-switcher-kit'),
  ('3cecfa44-e895-5e9a-a3c9-2d82ecc35a80', 'accessories-power-distribution', '48b5ed52-b7db-5155-976a-02ef53b7aaef', 'Power Distribution System', 'Certified power distribution and circuit management for technical loads of any scale.', 'Power distribution engineered and installed to venue code, with redundant circuits allocated to anything broadcast-critical — the infrastructure layer underneath every LED, audio, lighting, and camera system we deploy.', '[{"label":"Distribution","value":"Three-phase and single-phase distro boards"},{"label":"Circuit Protection","value":"RCD-protected, code-compliant"},{"label":"Redundancy","value":"Isolated backup circuits for critical loads"},{"label":"Cable Management","value":"Rated cabling with full run documentation"}]'::jsonb, ARRAY['Full-event power infrastructure', 'Broadcast-critical redundant circuits', 'Multi-vendor shared power environments']::text[], 'in-stock', 'accessories-power-distribution'),
  ('4ae382b4-d3d4-5065-81fe-1b6464035964', 'accessories-cable-management', '48b5ed52-b7db-5155-976a-02ef53b7aaef', 'Cable Ramp & Management Kit', 'Cable ramps, dressing, and pathway management for safe, clean cable runs across public areas.', 'Cable ramps and dressing systems used to route power and signal cable safely across public walkways and stage areas — a small detail that matters for both safety compliance and a clean production look.', '[{"label":"Ramp Types","value":"Single, dual, and 5-channel cable ramps"},{"label":"Load Rating","value":"Pedestrian and light vehicle rated"},{"label":"Compliance","value":"Meets venue and fire code walkway requirements"},{"label":"Finish","value":"High-visibility and low-profile options"}]'::jsonb, ARRAY['Public walkway cable crossings', 'Backstage cable dressing', 'Exhibition floor cable management']::text[], 'in-stock', 'accessories-cable-management'),
  ('a47e9740-67b0-5ac6-a72b-56475d45bb10', 'accessories-flight-cases', '48b5ed52-b7db-5155-976a-02ef53b7aaef', 'Flight Case & Transport Package', 'Road-rated flight cases and transport logistics for equipment moving between venues nationwide.', 'Road-rated cases and coordinated transport logistics for equipment moving between our facility and venues nationwide, or between multiple event sites on a multi-city program.', '[{"label":"Case Rating","value":"Road/flight-rated, foam-fitted per equipment set"},{"label":"Tracking","value":"Inventory-tracked per case and event"},{"label":"Transport","value":"Nationwide logistics coordination"},{"label":"Insurance","value":"In-transit coverage included"}]'::jsonb, ARRAY['Multi-city event tours', 'Nationwide equipment logistics', 'Secure equipment transport and storage']::text[], 'in-stock', 'accessories-flight-cases');
