insert into projects (id, slug, title, client, location, year, category, summary, description, stats, visual_seed) values
  ('b1e644a5-81c3-5ced-bea0-c02e2985cef2', 'meridian-robotics-apac-summit', 'APAC Partner Summit', 'Meridian Robotics', 'Tokyo', 2025, 'Hybrid', 'A two-day hybrid partner summit connecting in-room attendees in Tokyo with remote partners across nine countries and time zones.', ARRAY['Meridian Robotics needed their annual APAC partner summit to reach partners who couldn''t travel to Tokyo without compromising the in-room experience for the 220 attendees who could. We designed the event as two coordinated productions from the start — an in-room stage program and an independent broadcast — rather than adapting a standard conference format after the fact.', 'A dedicated broadcast technical director ran the stream on redundant dual-circuit internet, separate from the in-room stage management team, while simultaneous interpretation channels carried both Japanese and English audio to in-room and remote attendees alike.', 'The result held through both days without a streaming interruption, and remote attendees reported engagement levels close to in-room attendees based on Q&A participation — a metric Meridian now tracks as a standard success measure for future hybrid events.']::text[], '[{"label":"Attendees (in-room)","value":"220"},{"label":"Remote countries","value":"9"},{"label":"Stream uptime","value":"100%"}]'::jsonb, 'meridian-robotics-apac-summit'),
  ('111dc0f5-f3a7-5625-86d5-6ad143628c61', 'ridgeline-semiconductor-tech-expo', 'Tech Expo Booth & Product Reveal', 'Ridgeline Semiconductor', 'Osaka', 2025, 'Exhibition', 'A 120-square-meter exhibition booth with an integrated LED centerpiece and on-floor product reveal, built in a nine-hour load-in window.', ARRAY['Ridgeline''s booth needed to anchor their presence on a crowded show floor while accommodating a scheduled product reveal partway through the first show day — meaning the booth had to function as a standard exhibition space and, for fifteen minutes, as a small stage production.', 'We built a curved P2.6 indoor LED centerpiece as the booth''s visual anchor, with a lighting cue sequence pre-programmed for the reveal moment, executed within the hall''s strict nine-hour build window shared with dozens of neighboring exhibitors.', 'The booth held its calibration and cueing for the full three-day show, with our technicians on the floor throughout for live support rather than a build-and-leave arrangement.']::text[], '[{"label":"Booth footprint","value":"120m²"},{"label":"Build window","value":"9 hours"},{"label":"Show duration","value":"3 days"}]'::jsonb, 'ridgeline-semiconductor-tech-expo'),
  ('c3976b2a-22ff-521a-8ec0-a1e7902746df', 'sakura-financial-annual-meeting', 'Annual General Meeting', 'Sakura Financial Group', 'Tokyo', 2026, 'Corporate', 'A precisely run shareholder AGM with zero tolerance for technical error, broadcast to a secondary overflow room.', ARRAY['Shareholder meetings carry a different risk profile than most corporate events — the room notices any hesitation, and there is no second take. Sakura Financial Group''s AGM required flawless microphone handoffs between board members, exact timing against a legally-reviewed agenda, and a live overflow feed to a secondary room for shareholders beyond the main hall''s capacity.', 'We ran wireless microphone coordination tuned specifically to the venue''s dense RF environment, a redundant audio path to the overflow room, and a stage management team drilled specifically on the board''s prepared handoff sequence.', 'The meeting ran to schedule within minutes across a multi-hour agenda, with the overflow feed holding clean audio and video throughout.']::text[], '[{"label":"Attendees","value":"480"},{"label":"Overflow room feed","value":"Live, redundant"},{"label":"Agenda variance","value":"Under 3 minutes"}]'::jsonb, 'sakura-financial-annual-meeting'),
  ('0ca8748a-f216-53c6-838a-993782d39161', 'lumen-cosmetics-flagship-launch', 'Flagship Product Launch', 'Lumen Cosmetics', 'Tokyo', 2025, 'Corporate', 'A press and VIP product launch built around a single choreographed lighting and reveal sequence.', ARRAY['Lumen Cosmetics wanted their flagship launch to feel as considered as the product itself — a brief where lighting design carried as much weight as the physical staging. We designed the reveal around a synchronized lighting and LED cue sequence, rehearsed to the second across multiple full run-throughs before doors opened to press and VIP guests.', 'Multi-camera coverage captured the reveal for same-day press distribution and social assets, positioned to avoid any visible rigging or technical infrastructure in frame.', 'Post-event, Lumen''s marketing team used the multi-camera footage directly in their campaign rollout, a secondary benefit of designing the camera plan alongside the lighting plan from the start rather than as an afterthought.']::text[], '[{"label":"Guests","value":"180 (press & VIP)"},{"label":"Reveal cue accuracy","value":"Frame-exact"},{"label":"Camera positions","value":"4"}]'::jsonb, 'lumen-cosmetics-flagship-launch'),
  ('7dd536aa-9c50-51f9-bce1-844fd62ac545', 'nordholm-pharmaceuticals-research-symposium', 'International Research Symposium', 'Nordholm Pharmaceuticals', 'Yokohama', 2025, 'Conference', 'A three-track, two-day medical research symposium with full simultaneous interpretation across all sessions.', ARRAY['Nordholm''s symposium brought together researchers from twelve countries across three parallel session tracks, with simultaneous interpretation required in every room, not just the main stage — a materially larger interpretation footprint than most conferences of similar size.', 'We built three independently staffed interpretation booths, each with dedicated audio distribution, and stage-managed all three tracks in parallel to keep session changeovers synchronized across rooms so attendees moving between tracks never missed a session opening.', 'Every keynote and plenary session was also live streamed for researchers unable to travel, with recordings delivered to Nordholm within 48 hours for their internal research archive.']::text[], '[{"label":"Parallel tracks","value":"3"},{"label":"Interpretation booths","value":"3"},{"label":"Countries represented","value":"12"}]'::jsonb, 'nordholm-pharmaceuticals-research-symposium'),
  ('f53bcfb4-0ff6-50a7-b8cb-852eb93114df', 'orbit-mobility-outdoor-groundbreaking', 'Outdoor Groundbreaking Ceremony', 'Orbit Mobility', 'Nagoya', 2024, 'Outdoor', 'A daylight outdoor ceremony with a weatherproof LED screen and press-facing broadcast, built on an open construction site.', ARRAY['Orbit Mobility''s new facility groundbreaking took place on an active construction site with no fixed power or structural infrastructure — everything from power distribution to the outdoor stage had to be brought in and engineered for the site conditions.', 'A weatherproof outdoor LED screen carried live camera coverage of the ceremony to attendees seated at distance, readable clearly in direct midday sun, supported by a freestanding truss tower positioned clear of the ceremonial area.', 'Contingency planning covered wind loading and a same-day weather shift, both accounted for in the structural rigging plan before the event, not improvised on the day.']::text[], '[{"label":"Attendees","value":"150"},{"label":"Screen visibility","value":"Full daylight readable"},{"label":"Site power source","value":"Fully self-supplied"}]'::jsonb, 'orbit-mobility-outdoor-groundbreaking'),
  ('46c3aacf-2c60-514f-8990-81134216ecda', 'vantage-capital-investor-briefing', 'Global Investor Briefing', 'Vantage Capital Partners', 'Tokyo (Studio Production)', 2026, 'Virtual', 'A fully virtual quarterly investor briefing produced from a studio set with multi-speaker, multi-market coordination.', ARRAY['Vantage Capital''s quarterly investor briefing runs entirely virtual by design, but the brief was explicit: it should look and feel like a produced broadcast, not a video call. We built a studio set with broadcast lighting and multi-camera coverage, coordinating speakers dialing in from three separate offices alongside two presenters on-set in Tokyo.', 'A technical rehearsal against the live platform the day before caught a caption-sync issue on one remote speaker''s connection, resolved before the actual briefing rather than discovered live.', 'The finished broadcast ran without incident to an investor audience across four continents, with a same-day edited recording delivered for Vantage''s investor relations archive.']::text[], '[{"label":"Remote speaker locations","value":"3"},{"label":"Investor markets reached","value":"4 continents"},{"label":"Technical issues live","value":"0"}]'::jsonb, 'vantage-capital-investor-briefing'),
  ('ba83bf03-983b-517e-8c3f-f0597b4402ca', 'tsukiyo-hospitality-anniversary-gala', '20th Anniversary Gala & Award Ceremony', 'Tsukiyo Hospitality Group', 'Kyoto', 2025, 'Corporate', 'A formal anniversary gala combining ambient venue lighting design with a broadcast-style award presentation segment.', ARRAY['Tsukiyo''s 20th anniversary gala needed to shift tonally partway through the evening — from ambient reception lighting to a formal, camera-directed award presentation segment recognizing long-serving staff across their properties.', 'We designed a lighting program with two distinct cue states built into the same rig, transitioning the room''s mood without a visible reset, and brought in multi-camera coverage specifically for the awards segment to give Tsukiyo a polished internal recording for future use.', 'The evening''s run-of-show was held tightly to schedule despite a live program with unpredictable moments — several award recipients spoke longer than scripted, and the stage management team absorbed the variance without visibly disrupting the evening''s pacing.']::text[], '[{"label":"Guests","value":"300"},{"label":"Lighting cue states","value":"2 distinct programs"},{"label":"Award recipients","value":"24"}]'::jsonb, 'tsukiyo-hospitality-anniversary-gala');
